import type { ZodType } from 'zod'
import schema1 from '../generated/mb-species-1.schema.json'
import schema2 from '../generated/mb-species-2.schema.json'
import { speciesV1, speciesV2 } from '../generated/species.zod'

// The species file's schema in the page (R3). The JSON Schema is the server's (`GET /api/schema/mb-species-2`, written to src/generated by wb/schema_json.py), the zod schema and the TS types are made from it at build time
// (scripts/gen-zod.mjs), so a field's label, help, unit and band, the form's checks and the types are one thing. `validateSpecies` is the file-stage check in the browser: it says what the server's `validate` says, field for field
// (the server still has the last word on a save). What zod cannot hold is read off the JSON Schema's `x-` keys: the plan's bands, the keys a cage file or a mesh file needs, and the keys the schema names to refuse.
export type { SpeciesV1, SpeciesV2 } from '../generated/species.zod'

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Node = any
export const SCHEMAS: Record<string, { json: Node; zod: ZodType }> = { 'mb-species/1': { json: schema1, zod: speciesV1 }, 'mb-species/2': { json: schema2, zod: speciesV2 } }
export type Problem = { path: string; message: string }

const isObj = (v: unknown): v is Record<string, unknown> => typeof v === 'object' && v !== null && !Array.isArray(v)

// A property's node, whether or not it is wrapped as nullable (anyOf [node, null]).
export const bare = (n: Node): Node => (n?.anyOf ? { ...n.anyOf.find((x: Node) => x.type !== 'null'), title: n.title, description: n.description, 'x-unit': n['x-unit'], 'x-stage': n['x-stage'], 'x-range': n['x-range'] } : n)

/** The schema node at a dotted schema path: 'spine.tail.length', 'spine.ranges[].length', 'rig.bones[].len'. */
export function nodeAt(schemaId: string, path: string): Node | undefined {
  let cur: Node = SCHEMAS[schemaId]?.json
  for (const tok of path.replace(/\[\]/g, '.[]').split('.')) {
    if (!cur) return undefined
    cur = tok === '[]' ? bare(cur).items : bare(cur).properties?.[tok]
  }
  return cur && bare(cur)
}

export type FieldMeta = { label: string; help: string; unit: string; stage: string; range: [number, number] | null; options: unknown[] | null; kind: string }
/** What the schema says of one field: its words (the copywriter's, laid in by the server), unit, stage, the plan's band when a plan is given, and the kind that picks its control. */
export function fieldMeta(schemaId: string, path: string, plan?: string): FieldMeta | undefined {
  const n = nodeAt(schemaId, path)
  if (!n) return undefined
  const r = n['x-range']
  const band = Array.isArray(r) ? (r as [number, number]) : typeof r === 'string' ? ((SCHEMAS[schemaId].json['x-plans'][plan ?? '']?.[r] as [number, number] | undefined) ?? null) : null
  const kind = n.enum ? 'enum' : n.type === 'integer' ? 'int' : n.type === 'number' ? 'number' : n.type === 'string' ? 'text' : n.type === 'array' && n.maxItems ? (n.maxItems === 3 ? 'vec3' : 'pair') : n.type === 'array' ? 'list' : n.type === 'object' ? 'object' : 'free'
  return { label: n.title ?? '', help: n.description ?? '', unit: n['x-unit'] ?? '', stage: n['x-stage'] ?? '', range: band, options: n.enum ?? null, kind }
}

/** A pointer into a file ('/rig/bones/3/len') as the schema's path ('rig.bones[].len'). */
export const schemaPathOfPtr = (ptr: string): string => ptr.split('/').slice(1).map((t) => (/^\d+$/.test(t) ? '[]' : t)).join('.').replace(/\.\[\]/g, '[]')

/** Every field of the schema that has words, as [path, node]: lists show their item fields under `path[]`. */
export function* walkSchema(json: Node, prefix = ''): Generator<[string, Node]> {
  for (const [k, raw] of Object.entries<Node>(json.properties ?? {})) {
    const n = bare(raw)
    const p = `${prefix}${k}`
    yield [p, n]
    if (n.type === 'object' && n.properties) yield* walkSchema(n, `${p}.`)
    else if (n.type === 'array' && n.items?.properties) yield* walkSchema(n.items, `${p}[].`)
  }
}

const dotted = (path: (string | number)[], doc: unknown): string => {
  // A list item reads by its id where the schema names the key (the server says 'parts.leg.L.chain', not 'parts.2.chain').
  const out: string[] = []
  let cur: unknown = doc
  for (const p of path) {
    const next = Array.isArray(cur) || isObj(cur) ? (cur as Record<string | number, unknown>)[p] : undefined
    out.push(typeof p === 'number' && isObj(next) && typeof (next.id ?? next.part ?? next.name) === 'string' ? String(next.id ?? next.part ?? next.name) : String(p))
    cur = next
  }
  return out.join('.')
}

function bandProblems(json: Node, plan: Node, doc: Record<string, unknown>, out: Problem[]) {
  const unit = (n: Node) => (n['x-unit'] ? ` ${n['x-unit']}` : '')
  const walk = (node: Node, val: unknown, path: (string | number)[]) => {
    const n = bare(node)
    if (n.type === 'number' && typeof n['x-range'] === 'string' && typeof val === 'number') {
      const r = plan?.[n['x-range']] as [number, number] | undefined
      if (r && !(r[0] <= val && val <= r[1])) {
        const p = dotted(path, doc)
        out.push({ path: p, message: n['x-unit'] === '%' ? `${p} is +${+(val * 100).toPrecision(6)} %; the ${plan.name} plan allows +${r[0] * 100} to +${r[1] * 100} %` : `${p} is ${val}${unit(n)}; the ${plan.name} plan allows ${r[0]} to ${r[1]}` })
      }
    } else if (n.type === 'object' && n.properties && isObj(val)) {
      for (const [k, sub] of Object.entries<Node>(n.properties)) if (k in val) walk(sub, val[k], [...path, k])
    } else if (n.type === 'array' && n.items?.properties && Array.isArray(val)) {
      val.forEach((it, i) => { if (isObj(it)) for (const [k, sub] of Object.entries<Node>(n.items.properties)) if (k in it) walk(sub, it[k], [...path, i, k]) })
    }
  }
  walk({ ...json, type: 'object' }, doc, [])
}

const kindOf = (v: unknown): string => (v === null || v === undefined ? 'nothing' : typeof v === 'boolean' ? 'true or false' : typeof v === 'number' ? 'a number' : typeof v === 'string' ? 'text' : Array.isArray(v) ? 'a list' : 'an object')
// What a zod issue says, in the server's words for the same fault ("must be a number, got text").
function said(i: { code: string; message: string; path: PropertyKey[]; expected?: string; values?: unknown[]; origin?: string }, doc: unknown, schemaId: string): string {
  let v: unknown = doc
  for (const p of i.path) v = (v as Record<PropertyKey, unknown> | undefined)?.[p]
  const n = nodeAt(schemaId, schemaPathOfPtr('/' + i.path.map(String).join('/')))
  if (i.code === 'invalid_type' || (i.code === 'too_small' || i.code === 'too_big') && i.origin === 'array') {
    if (n?.type === 'array' && n.maxItems) return `must be ${n.maxItems === 3 ? 'three numbers (x, y, z)' : 'two numbers (start and end)'}, got ${kindOf(v)}`
    const want = { number: 'a number', int: 'a whole number', string: 'text', boolean: 'true or false', array: 'a list', object: 'an object' }[i.expected ?? ''] ?? i.expected
    return `must be ${n?.type === 'integer' ? 'a whole number' : want}, got ${kindOf(v)}`
  }
  if (i.code === 'invalid_value' && i.values) return `'${String(v)}' is not one of ${i.values.join(', ')}`
  return i.message
}

/** The file-stage check in the browser: the same fields the server's `validate` names, with the plan's bands, the plan's ranges and the tail shares. An empty list is a valid file. */
export function validateSpecies(doc: unknown): Problem[] {
  if (!isObj(doc)) return [{ path: '', message: 'the file must be an object' }]
  const s = SCHEMAS[String(doc.schema)]
  if (!s) return [{ path: 'schema', message: `schema: must be 'mb-species/1' or 'mb-species/2', got ${JSON.stringify(doc.schema)}` }]
  const out: Problem[] = []
  const json = s.json
  const mesh = doc.schema === 'mb-species/2' && 'mesh' in doc
  const need: string[] = mesh ? json['x-required'].mesh : json['x-required'].cage
  for (const k of need) if (!(k in doc)) out.push({ path: k, message: `${k}: missing (it is required: ${bare(json.properties[k] ?? {}).description ?? ''})` })
  if (mesh) {
    const both = ['spine', 'skeleton', 'parts'].filter((k) => k in doc)
    if (both.length) return [{ path: both[0], message: `${both[0]}: a file has either the cage fields (spine, skeleton, parts) or mesh, never both` }]          // the server stops here too
  }
  const r = s.zod.safeParse(doc)
  if (!r.success) {
    for (const i of r.error.issues) {
      const path = dotted(i.path as (string | number)[], doc)
      if (i.code === 'unrecognized_keys') {
        const parentNode = i.path.length ? nodeAt(String(doc.schema), schemaPathOfPtr('/' + i.path.map(String).join('/'))) : json
        for (const k of i.keys) out.push({ path: path ? `${path}.${k}` : k, message: `${path ? path + '.' : ''}${k}: ${parentNode?.['x-refused']?.[k] ?? `not a field of ${doc.schema}`}; fields that are not listed are rejected` })
      } else if (!out.some((p) => p.path === path)) out.push({ path, message: `${path}: ${said(i, doc, String(doc.schema))}` })              // a missing key is said once, whoever finds it first
    }
  }
  const plan = json['x-plans'][String(doc.plan)]
  if (!plan) out.push({ path: 'plan', message: `plan: '${String(doc.plan)}' is not a registered plan` })
  else {
    bandProblems(json, plan, doc, out)
    const sp = isObj(doc.spine) ? doc.spine : null
    const rg = sp && Array.isArray(sp.ranges) ? (sp.ranges as Record<string, unknown>[]) : null
    if (rg && rg.every(isObj)) {
      const names = rg.map((x) => x.name)
      if (names.join() !== plan.ranges.join()) out.push({ path: 'spine.ranges', message: `spine.ranges: the ${plan.name} plan's ranges are ${plan.ranges.join(', ')} in that order, got ${names.join(', ')}` })
      else for (const x of rg) {
        const lh = plan.range_len?.[String(x.name)] as [number, number] | undefined
        if (lh && typeof x.length === 'number' && !(lh[0] <= x.length && x.length <= lh[1])) out.push({ path: `spine.ranges.${x.name}.length`, message: `spine.ranges.${x.name}.length is ${x.length} H; the ${plan.name} plan allows ${lh[0]} to ${lh[1]}` })
      }
    }
    const segs = sp && isObj(sp.tail) && Array.isArray(sp.tail.segments) ? (sp.tail.segments as Record<string, unknown>[]) : null
    if (segs?.length && segs.every((x) => isObj(x) && typeof x.share === 'number')) {
      const tot = segs.reduce((a, x) => a + (x.share as number), 0)
      if (Math.abs(tot - 1) > 1e-6) out.push({ path: 'spine.tail.segments', message: `spine.tail.segments: the shares add up to ${+tot.toPrecision(4)}, they must add up to 1` })
    }
  }
  return out
}
